args.sparql:
SELECT ?film ?filmLabel ?director ?directorBirthDate WHERE {
  VALUES ?film { dbr:Traces_of_a_Dragon dbr:Moonnupookkal }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?directorBirthDate . }
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER (lang(?filmLabel) = 'en') }
}
ORDER BY DESC(?directorBirthDate)
LIMIT 1

